text:
/* Colors for the message notification type */
&.in-app-notification-message {
  --title-text: var(--color-text-warning);
  --border-color: #caa204;
  --button-background: linear-gradient(var(--color-yellow-40), #eabd08);
  --button-stroke: var(--border-color);
  --button-background-hover: var(--button-background);
  --button-background-active: var(--border-color);
  --button-focus-ring: var(--border-color);
  --button-text: var(--color-gray-90);
  --content-border: var(--border-color);
  --container-border: var(--border-color);
  --icon-url: url("chrome://messenger/skin/icons/new/compact/error-circle.svg");
  --icon-fill: #e1b555;
  --icon-stroke: var(--color-yellow-90);
  --container-background: linear-gradient(#ffdf8d, #fac439);
  --content-background: linear-gradient(#fefae8, #f7f7f7);

  @media (prefers-contrast: more) {
    --content-border: #eabd08;
    --icon-stroke: #eabd08;
    --icon-fill: transparent;
  }
}

/* Colors for the security notification type */
&.in-app-notification-security {
  --title-text: var(--color-text-critical);
  --button-stroke: var(--color-red-90);
  --button-background: linear-gradient(#cb1f1f, var(--color-red-90));
  --button-background-active: var(--color-red-90);
  --button-background-hover: var(--button-background);
  --button-text: var(--color-gray-05);
  --button-focus-ring: var(--color-red-50);
  --content-border: light-dark(var(--color-red-90), var(--color-red-50));
  --container-border: light-dark(var(--color-red-90), var(--color-red-50));
  --icon-url: url("chrome://messenger/skin/icons/new/compact/warning.svg");
  --icon-fill: #c7484a;
  --icon-stroke: var(--color-white);
  --container-background: linear-gradient(var(--color-red-70), var(--color-red-80));
  --content-background: linear-gradient(#fef2f2, #f7f7f7);

  @media (prefers-color-scheme: dark) {
    --container-background: linear-gradient(var(--color-red-70), var(--color-red-30));
  }

  @media (prefers-contrast: more) {
    --content-border: var(--color-red-50);
    --icon-stroke: var(--color-red-50);
    --icon-fill: transparent;
  }
